{
  "items": [
    {
      "name": "setOf_liouvilleWith_subset_aux",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Measure",
      "kind": "theorem",
      "type": "{x | ∃ p > 2, LiouvilleWith p x} ⊆\n  ⋃ m,\n    (fun x => x + ↑m) ⁻¹'\n      ⋃ n, ⋃ (_ : n > 0), {x | ∃ᶠ (b : ℕ) in Filter.atTop, ∃ a ∈ Finset.Icc 0 ↑b, |x - ↑a / ↑b| < 1 / ↑b ^ (2 + 1 / ↑n)}"
    },
    {
      "name": "LiouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "definition",
      "type": "ℝ → ℝ → Prop"
    },
    {
      "name": "Real.infinite_rat_abs_sub_lt_one_div_den_sq_of_irrational",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ : ℝ}, Irrational ξ → {q | |ξ - ↑q| < 1 / ↑q.den ^ 2}.Infinite"
    },
    {
      "name": "Real.exists_rat_abs_sub_lt_and_lt_of_irrational",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ : ℝ}, Irrational ξ → ∀ (q : ℚ), ∃ q', |ξ - ↑q'| < 1 / ↑q'.den ^ 2 ∧ |ξ - ↑q'| < |ξ - ↑q|"
    },
    {
      "name": "Liouville",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "definition",
      "type": "ℝ → Prop"
    },
    {
      "name": "Rat.den_le_and_le_num_le_of_sub_lt_one_div_den_sq",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ q : ℚ}, |ξ - q| < 1 / ↑q.den ^ 2 → q.den ≤ ξ.den ∧ ⌈ξ * ↑q.den⌉ - 1 ≤ q.num ∧ q.num ≤ ⌊ξ * ↑q.den⌋ + 1"
    },
    {
      "name": "Real.infinite_rat_abs_sub_lt_one_div_den_sq_iff_irrational",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℝ), {q | |ξ - ↑q| < 1 / ↑q.den ^ 2}.Infinite ↔ Irrational ξ"
    },
    {
      "name": "LiouvilleWith.frequently_lt_rpow_neg",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p q x : ℝ}, LiouvilleWith p x → q < p → ∃ᶠ (n : ℕ) in Filter.atTop, ∃ m, x ≠ ↑m / ↑n ∧ |x - ↑m / ↑n| < ↑n ^ (-q)"
    },
    {
      "name": "Liouville.exists_pos_real_of_irrational_root",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "theorem",
      "type": "∀ {α : ℝ},\n  Irrational α →\n    ∀ {f : Polynomial ℤ},\n      f ≠ 0 →\n        Polynomial.eval α (Polynomial.map (algebraMap ℤ ℝ) f) = 0 →\n          ∃ A, 0 < A ∧ ∀ (a : ℤ) (b : ℕ), 1 ≤ (↑b + 1) ^ f.natDegree * (|α - ↑a / (↑b + 1)| * A)"
    },
    {
      "name": "Liouville.frequently_exists_num",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, Liouville x → ∀ (n : ℕ), ∃ᶠ (b : ℕ) in Filter.atTop, ∃ a, x ≠ ↑a / ↑b ∧ |x - ↑a / ↑b| < 1 / ↑b ^ n"
    },
    {
      "name": "ae_not_liouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Measure",
      "kind": "theorem",
      "type": "∀ᵐ (x : ℝ), ∀ p > 2, ¬LiouvilleWith p x"
    },
    {
      "name": "Behrend.roth_lower_bound",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, ↑N * Real.exp (-4 * √(Real.log ↑N)) ≤ ↑(rothNumberNat N)"
    }
  ]
}
